import {readFileSync} from "node:fs";
import {resolve,relative} from "node:path";
import {createHash} from "node:crypto";
import {withPackLock,loadPackWithMeta,savePack} from "/home/videogamer/code/memex_beta/treadle/packages/core/src/index.ts";
const [dirArg,revisionArg,proposalArg] = process.argv.slice(2);
const dir=resolve(dirArg);
const held=Number(revisionArg);
const proposal=JSON.parse(proposalArg);
const result=withPackLock(dir,()=>{
 const loaded=loadPackWithMeta(dir); if(!loaded.ok) throw Error(JSON.stringify(loaded));
 const {doc,path}=loaded.value;
 if(doc.revision!==held) throw Error("held revision mismatch");
 if(doc.status==="complete" || doc.closed_at) throw Error("closed pack");
 if(doc.approved_at || doc.tasks.length || doc.plan.decisions?.some(d=>d.status==="accepted") || doc.workflow?.acts.length || doc.workflow?.pending_audit.length) throw Error("bound or pending authority: stop without mutation");
 const preserved=JSON.stringify({questions:doc.spec.clarifications,decisions:doc.plan.decisions,tasks:doc.tasks,workflow:doc.workflow,review:doc.review,env:doc.env});
 const existing=(doc.spec.requirements??[]) as {id:string}[];
 for(const req of proposal.requirements){const old=existing.find(r=>r.id===req.id); if(old&&JSON.stringify(old)!==JSON.stringify(req))throw Error("conflicting requirement "+req.id);}
 doc.spec.requirements=[...existing,...proposal.requirements.filter((r:{id:string})=>!existing.some(e=>e.id===r.id))];
 doc.spec.out_of_scope=[...new Set([...(doc.spec.out_of_scope??[]) as string[],...proposal.out_of_scope])];
 doc.artifacts={...doc.artifacts};
 for(const [id,file] of Object.entries(proposal.artifacts) as [string,string][]){
  const full=resolve(dir,file); if(relative(dir,full).startsWith(".."))throw Error("artifact escapes pack");
  const entry={file,type:"text/markdown",sha256:createHash("sha256").update(readFileSync(full)).digest("hex")};
  if(doc.artifacts[id]&&JSON.stringify(doc.artifacts[id])!==JSON.stringify(entry))throw Error("existing artifact conflict");
  doc.artifacts[id]=entry;
 }
 doc.revision=held+1;
 const persistence=savePack(doc,path,{at:new Date().toISOString()});
 if(persistence?.audit_pending || persistence?.durability_error)throw Error("published with recovery need "+JSON.stringify(persistence));
 const reload=loadPackWithMeta(dir); if(!reload.ok)throw Error(JSON.stringify(reload));
 const published=reload.value.doc;
 if(published.revision!==held+1 || JSON.stringify(published.spec.requirements)!==JSON.stringify(doc.spec.requirements))throw Error("reload mismatch");
 const after=JSON.stringify({questions:published.spec.clarifications,decisions:published.plan.decisions,tasks:published.tasks,workflow:published.workflow,review:published.review,env:published.env});
 if(preserved!==after)throw Error("preserved record mismatch");
 for(const [id,entry] of Object.entries(published.artifacts??{}))if(entry.sha256!==createHash("sha256").update(readFileSync(resolve(dir,entry.file))).digest("hex"))throw Error("artifact pin mismatch "+id);
 return {path:reload.value.path,revision:published.revision,requirements:published.spec.requirements,artifacts:published.artifacts,workflow:published.workflow,decisions:published.plan.decisions,persistence,preserved:true};
});
if(!result.ok)throw Error(JSON.stringify(result));
console.log(JSON.stringify(result.value,null,2));

