import {loadPackWithMeta,savePack,withPackLock} from "/home/videogamer/code/memex_beta/treadle/packages/core/src/index.ts";
import {readFileSync,writeFileSync} from "node:fs";
import {resolve,join} from "node:path";
import {createHash} from "node:crypto";
const input=JSON.parse(readFileSync("registration-data.json","utf8"));
const dir=resolve(input.pack), held=Number(process.argv[2]);
const result=withPackLock(dir,()=>{
 const loaded=loadPackWithMeta(dir); if(!loaded.ok) throw Error(JSON.stringify(loaded));
 const {doc,path}=loaded.value;
 if(doc.revision!==held) throw Error("Held revision mismatch");
 if(doc.status==="complete") throw Error("Frozen pack");
 if(doc.approved_at || doc.tasks.length || doc.workflow?.start_receipt || doc.workflow?.acts.length || doc.workflow?.pending_audit.length || doc.plan.decisions?.some(d=>d.status==="accepted")) throw Error("Bound fields or pending audit; preserve record");
 const prior={workflow:JSON.stringify(doc.workflow),decisions:JSON.stringify(doc.plan.decisions),questions:JSON.stringify(doc.spec.clarifications),tasks:JSON.stringify(doc.tasks)};
 const requirements=doc.spec.requirements as any[];
 for(const r of input.requirements) {if(requirements.some(x=>x.id===r.id)) throw Error("Requirement ID conflict");requirements.push(r);}
 const exclusions=doc.spec.out_of_scope as string[];
 for(const exclusion of input.exclusions) if(!exclusions.includes(exclusion)) exclusions.push(exclusion);
 doc.artifacts??={};
 for(const [id,file] of Object.entries(input.artifacts) as [string,string][]) {
  if(doc.artifacts[id]) throw Error("Artifact ID conflict");
  doc.artifacts[id]={file,type:"text/markdown",sha256:createHash("sha256").update(readFileSync(join(dir,file))).digest("hex")};
 }
 doc.revision=held+1;
 const saved=savePack(doc,path,{at:new Date().toISOString()});
 if(saved?.audit_pending || saved?.durability_error) throw Error(JSON.stringify(saved));
 const published=loadPackWithMeta(dir); if(!published.ok) throw Error(JSON.stringify(published));
 if(published.value.doc.revision!==held+1) throw Error("Revision publication failed");
 const d=published.value.doc;
 if(JSON.stringify(d.workflow)!==prior.workflow || JSON.stringify(d.plan.decisions)!==prior.decisions || JSON.stringify(d.spec.clarifications)!==prior.questions || JSON.stringify(d.tasks)!==prior.tasks) throw Error("Unrelated field changed");
 for(const [id,artifact] of Object.entries(d.artifacts!)) if(createHash("sha256").update(readFileSync(join(dir,artifact.file))).digest("hex")!==artifact.sha256) throw Error("Artifact digest mismatch: "+id);
 const report={path:published.value.path,revision:d.revision,format:d.format,policy:d.workflow?.policy,question_state:d.workflow?.phase_questions,requirements:d.spec.requirements,artifacts:d.artifacts,preserved_workflow:true,saved};
 writeFileSync("registration-result.json",JSON.stringify(report,null,2)+"\n");
 return report;
});
if(!result.ok) throw Error(JSON.stringify(result)); console.log(JSON.stringify(result.value));

