const result=withPackLock(dir,()=>{
 const loaded=loadPackWithMeta(dir); if(!loaded.ok)throw Error(loaded.message);
 const {doc,path}=loaded.value;
 assert.equal(doc.revision,2); assert.equal(doc.status,'active');
 assert.equal(doc.approved_at,undefined); assert.equal(doc.workflow?.start_receipt,undefined);
