 const retained=JSON.stringify({decisions:doc.plan.decisions,workflow:doc.workflow,tasks:doc.tasks,clarifications:doc.spec.clarifications});
 doc.spec.requirements=[
  {id:'FR-1',text:'MUST establish whether raw list output preserves boundaries for unrestricted ordered id/title strings.',priority:'P1',scenarios:[{id:'AC-1',given:'Distinct arrays with actual TAB/LF in id/title',when:'Rendered by current list',then:'Deciding assertions capture whether output bytes collide'}]},
  {id:'FR-2',text:'MUST preserve current product renderer and supplied scratch diagnostic during analysis.',priority:'P1',scenarios:[{id:'AC-2',given:'Original product and scratch hashes',when:'The analysis concludes',then:'Hashes remain unchanged and no production exporter is shipped'}]}
 ];
 doc.spec.out_of_scope=['Shipping bulk exporter','Changing existing list','Selecting production output format','Storage or provider changes'];
 doc.artifacts={...(doc.artifacts??{})};
 for(const [key,file] of [['analysis','spike-1-boundaries.md'],['brief','brief.md'],['spec','spec.md'],['probe','boundary-probe.ts']]){
  assert.equal(doc.artifacts[key],undefined);
  doc.artifacts[key]={file,type:file.endsWith('.md')?'text/markdown':'text/typescript',sha256:createHash('sha256').update(readFileSync(join(dir,file))).digest('hex')};
 }
 assert.equal(JSON.stringify({decisions:doc.plan.decisions,workflow:doc.workflow,tasks:doc.tasks,clarifications:doc.spec.clarifications}),retained);
 doc.revision=3;
