// THROWAWAY: deciding experiment only; never production exporter code.
import {list} from '../../src/list.ts';
import {strict as assert} from 'node:assert';
const TAB=String.fromCharCode(9), LF=String.fromCharCode(10);
const cases=[
 {name:'title newline creates extra record', a:[{id:'a',title:`b${LF}c${TAB}d`}], b:[{id:'a',title:'b'},{id:'c',title:'d'}]},
 {name:'id newline creates extra record', a:[{id:`a${TAB}b${LF}c`,title:'d'}], b:[{id:'a',title:'b'},{id:'c',title:'d'}]},
 {name:'tab shifts field boundary', a:[{id:`a${TAB}b`,title:'c'}], b:[{id:'a',title:`b${TAB}c`}]}
];
for(const c of cases){
 assert.notDeepEqual(c.a,c.b);
 const x=list(c.a), y=list(c.b);
 assert.equal(x,y, c.name);
 assert.ok(x.includes(TAB));
 console.log(JSON.stringify({name:c.name,a:c.a,b:c.b,x,y,codepoints:[...x].map(v=>v.charCodeAt(0)),collision:true}));
}
assert.equal(list([]),'');
assert.equal(list([{id:'second',title:'Two'},{id:'first',title:'One'}]),`second${TAB}Two${LF}first${TAB}One`);
console.log('All deciding assertions passed; empty/order controls passed.');

