// Throwaway analysis authoring adapter. No owner actions.
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {resolve,join} from 'node:path';
import {withPackLock,loadPackWithMeta,savePack} from '/home/videogamer/code/memex_beta/treadle/packages/core/src/index.ts';
const packDir=resolve('specs/csv-export');
const held=3;
const candidate=[["FR-1","Export MUST emit exactly id and title columns with a first header record id,title.","AC-1","two notes with other possible metadata","CSV is exported","the header is id,title and each data record has exactly id then title"],["FR-2","Export MUST preserve current list input order without sorting or dropping records.","AC-2","notes ordered b then a","CSV is exported","data records remain b then a and all records are present"],["FR-3","Export MUST correctly quote fields containing commas, double quotes, CR or LF, doubling embedded double quotes and preserving string contents.","AC-3","id/title values containing comma, quote, CR, LF, empty strings and Unicode","CSV is exported","a CSV parser recovers the exact two original strings for every row"],["FR-4","The explicit local export operation MUST write CSV data to stdout.","AC-4","a scoped export entry point and supplied notes","the export command runs","captured stdout contains CSV only and invocation succeeds"],["FR-5","An empty note list MUST export the header record only.","AC-5","an empty list","CSV is exported","there is one header record id,title and no data records"],["FR-6","Existing text listing MUST retain its current bytes and order, including empty-string output for empty input.","AC-6","existing note arrays and empty input","existing text list is called after export is added","outputs equal current baseline including tab and LF separators and empty string"],["FR-7","Export MUST run locally without a new dependency or network service.","AC-7","the export implementation and project configuration","dependencies and runtime calls are inspected","no dependency is introduced and export performs no network request or service call"]].map(r=>({id:r[0],text:r[1],priority:'P1',scenarios:[{id:r[2],given:r[3],when:r[4],then:r[5]}],refs:['spec#Requirements']}));
const result=withPackLock(packDir,()=>{
 const loaded=loadPackWithMeta(packDir);
 if(!loaded.ok) throw Error(JSON.stringify(loaded));
 const {doc,path}=loaded.value;
 if(doc.revision!==held) throw Error('held revision mismatch');
 if(doc.status==='complete'||doc.approved_at||doc.approved_by||doc.tasks.length||(doc.plan.decisions??[]).some(d=>d.status==='accepted')||doc.workflow?.start_receipt||doc.workflow?.acts.length||doc.workflow?.pending_audit.length) throw Error('bound authority or audit state: stop');
 if((doc.spec.requirements as unknown[]).length) throw Error('unexpected existing candidate IDs');
 doc.spec.requirements=candidate;
 doc.spec.out_of_scope=['CSV import','Sorting/filtering and extra columns','File-output destinations','New dependencies or network services','Storage migration and accounts/UI','Replacing text listing'];
 doc.artifacts={...(doc.artifacts??{})};
 for(const [id,file] of Object.entries({analysis:'feature.md',brief:'brief.md',spec:'spec.md'})){
  if(doc.artifacts[id]) throw Error('artifact ID conflict');
  doc.artifacts[id]={file,type:'text/markdown',sha256:createHash('sha256').update(readFileSync(join(packDir,file))).digest('hex')};
 }
 doc.revision=held+1;
 const persisted=savePack(doc,path,{at:new Date().toISOString()});
 if(persisted?.audit_pending||persisted?.durability_error) throw Error('persistence requires recovery '+JSON.stringify(persisted));
 return {path,revision:doc.revision,persisted};
});
if(!result.ok) throw Error(JSON.stringify(result));
console.log(JSON.stringify(result));
const reloaded=loadPackWithMeta(packDir); if(!reloaded.ok) throw Error(JSON.stringify(reloaded));
console.log(JSON.stringify({revision:reloaded.value.doc.revision,format:reloaded.value.doc.format,requirements:reloaded.value.doc.spec.requirements,artifacts:reloaded.value.doc.artifacts,workflow:reloaded.value.doc.workflow,decisions:reloaded.value.doc.plan.decisions}));

