const result=withPackLock(dir,()=>{
 const loaded=loadPackWithMeta(dir);assert(loaded.ok);const {doc,path}=loaded.value;assert.equal(doc.revision,3);assert.notEqual(doc.status,'complete');assert.equal(doc.workflow?.pending_audit.length,0);assert(!doc.workflow?.start_receipt);assert(!doc.approved_at);
 doc.spec.requirements=[{id:'FR-1',text:'The candidate MUST preserve the local output contract.'}];doc.spec.out_of_scope=['Implementation and owner acts'];
 doc.artifacts={...doc.artifacts,...Object.fromEntries(['analysis','brief','spec','design','plan'].map(id=>[id,{file:id+'.md',type:'text/markdown',sha256:hash(readFileSync(join(dir,id+'.md')))}]))};
 doc.revision=4; const saved=savePack(doc,path,{at:new Date().toISOString()});assert(!saved?.durability_error);assert.equal(saved?.audit_pending,0);
});assert(result.ok);
const loaded=loadPackWithMeta(dir);assert(loaded.ok);const {doc,path}=loaded.value;
assert.equal(doc.revision,4);assert.deepEqual(doc.workflow,old.workflow);assert.deepEqual(doc.plan,old.plan);assert.deepEqual(doc.tasks,old.tasks);assert.deepEqual(doc.spec.clarifications,old.spec.clarifications);
