const beforeBytes=readFileSync(record); const nested=withPackLock(dir,()=>withPackLock(dir,()=>{throw Error('Should not enter another writer');}));assert(nested.ok&&!nested.value.ok);assert.equal(hash(readFileSync(record)),hash(beforeBytes));
let stale=false;try{withPackLock(dir,()=>{const l=loadPackWithMeta(dir);assert(l.ok);if(l.value.doc.revision!==3)throw Error('Held revision mismatch');throw Error('Unexpected stale acceptance');});}catch(e){stale=(e as Error).message==='Held revision mismatch';}assert(stale);assert.equal(hash(readFileSync(record)),hash(beforeBytes));
