writeFileSync(join(dir,'snapshot.json'),JSON.stringify({fixture:true}));assert(loadPackWithMeta(dir).ok);const c=await context(workspace,join(workspace,'isolated-state'));assert(c.specs.packs.some(p=>p['stage']==='refused'));
const a=alignment(doc);assert(a.ok);console.log(JSON.stringify({locked_writer:'passed',canonical_schema:'passed',preserved_workflow_decisions_questions_tasks:true,held_revision_refused:true,nested_writer_refused:true,successor_preserves_original_and_digest:true,core_loads_json_sidecar:true,context_still_refuses_sidecar:true,alignment:{violations:a.value.violations,gaps:gapCount(a.value)},revision:doc.revision,owner_acts:doc.workflow?.acts.length},null,2));

